// A module `dartvel add` generates asks for the Dartvel it was generated by.
//
// It asked for dartvel_core ^0.9.0, a caret that stops below 0.10.0. That
// excluded every release from 0.10.0 on, so a generated module could only
// resolve beside its parent through the parent's path overrides, and once
// the version line moved to 3.47 it named a range nothing current is in.
import 'dart:io';

import 'package:dartvel_cli/src/modules/described_api.dart';
import 'package:dartvel_cli/src/modules/foreign/dart_package_module.dart';
import 'package:dartvel_cli/src/modules/foreign/dart_surface.dart';
import 'package:dartvel_cli/src/modules/foreign/module_writer.dart';
import 'package:dartvel_cli/src/templates/project_templates.dart';
import 'package:path/path.dart' as p;
import 'package:pub_semver/pub_semver.dart';
import 'package:test/test.dart';
import 'package:yaml/yaml.dart';

void main() {
  late Directory root;
  setUp(() => root = Directory.systemTemp.createTempSync('dv_module_writer_'));
  tearDown(() => root.deleteSync(recursive: true));

  DVGeneratedModule generate() {
    final Directory vendor = Directory(p.join(root.path, 'slugs'))
      ..createSync();
    File(p.join(vendor.path, 'pubspec.yaml'))
        .writeAsStringSync('name: slugs\nversion: 1.0.0\n');
    File(p.join(vendor.path, 'lib', 'slugs.dart'))
      ..parent.createSync(recursive: true)
      ..writeAsStringSync('String slug(String text) => text.toLowerCase();\n');
    return dvWriteForeignModule(dvDartPackageModuleSpec(
      id: 'slugs',
      source: 'path:slugs',
      surface: dvScanDartPackage(vendor.path),
      dependency: '{path: ../slugs}',
    ));
  }

  test('the generated module admits the Dartvel this CLI belongs to', () {
    final YamlMap pubspec =
        loadYaml(generate().files['pubspec.yaml']!) as YamlMap;
    final String constraint =
        (pubspec['dependencies'] as YamlMap)['dartvel_core'] as String;
    expect(constraint, '^$dartvelPackageVersion');
    expect(
      VersionConstraint.parse(constraint)
          .allows(Version.parse(dartvelPackageVersion)),
      isTrue,
    );
  });

  test('the same source generates the same wrapper, so the lock stays stable',
      () {
    expect(dvWrapperHash(generate().files), dvWrapperHash(generate().files));
  });
}
